// Des: CLI dispatch: help, status, caps, login, run, pause, stop, resume, log
// Flo: read argv > parse ladder flags > build Ctx > call the command > exit code
// I/O: process Init (main) > u8 exit code 0-4; text on stdout
// ===================================================================
const std = @import("std"); const targ = @import("ct-ctrl-args.zig"); const ctxz = @import("ct-ctrl-ctxz.zig"); const stat = @import("ct-comm-stat.zig"); const halt = @import("ct-comm-halt.zig"); const logi = @import("ct-comm-logi.zig"); const runz = @import("ct-comm-runz.zig");
pub const HELP = "za: works Zalo Web for you at a human pace\n  za status [--json]            ready or halted, caps used\n  za caps [--json]              sends left this hour and today\n  za login                      open Zalo, scan the QR once\n  za run <job> [words] [flags]  jobs: read reply summ say send remind pin mute group forward canary\n  za pause | stop | resume      stop all jobs at the next action, or let them go again\n  za log [--json]               last 20 activity rows\nflags: --read (look only) · --dry (default: preview, change nothing) · --live (act) · --live --force (bulk, group, forward) · --json · --mock · --conf <file>\nexit: 0 ok · 1 fail · 2 usage · 3 finding · 4 blocked\n";
pub fn runMain(init: std.process.Init) !u8 { const allo = init.arena.allocator(); var iter = try init.minimal.args.iterateAllocator(allo); _ = iter.next(); var argv: std.ArrayList([]const u8) = .empty; while (iter.next()) |item| try argv.append(allo, item); const args = try targ.parse(allo, argv.items); var ctx = try ctxz.make(init, args); if (std.mem.eql(u8, args.cmd, "help")) { try ctxz.emit(&ctx, HELP); return 0; } if (std.mem.eql(u8, args.cmd, "status")) return stat.statRun(&ctx); if (std.mem.eql(u8, args.cmd, "caps")) return stat.capsRun(&ctx); if (std.mem.eql(u8, args.cmd, "log")) return halt.logRun(&ctx); if (std.mem.eql(u8, args.cmd, "pause")) return halt.pauseRun(&ctx, "paused by owner"); if (std.mem.eql(u8, args.cmd, "stop")) return halt.pauseRun(&ctx, "stopped by owner"); if (std.mem.eql(u8, args.cmd, "resume")) return halt.resumeRun(&ctx); if (std.mem.eql(u8, args.cmd, "login")) return logi.loginRun(&ctx); if (std.mem.eql(u8, args.cmd, "run")) return runz.runRun(&ctx); return error.BadUsage; }
